//! Auto-generated compact codon frequency tables.
//! Generated from src/cai/cai.rs by scripts/generate_codon_table_rs.py

/// Compact codon frequency table.
///
/// Codons are encoded as 6-bit integers: A=0, C=1, G=2, T=3,
/// so index = (base0 << 4) | (base1 << 2) | base2, range 0..64.
pub struct CodonTable {
    /// Frequency for each of the 64 codons.
    pub freqs: [f64; 64],
    /// Precomputed maximum frequency for each amino acid (see `AA_CHARS`).
    pub max_freq: [f64; 21],
}

impl CodonTable {
    /// Frequency of a codon given its 6-bit index.
    #[inline]
    pub fn freq_by_idx(&self, idx: u8) -> f64 {
        self.freqs[idx as usize]
    }

    /// Frequency of a codon given as a 3-byte DNA string.
    #[inline]
    #[allow(dead_code)]
    pub fn freq(&self, codon: &[u8]) -> f64 {
        self.freqs[codon_to_idx(codon) as usize]
    }

    /// CAI ratio (freq / max_freq_for_aa) for a codon string.
    #[inline]
    pub fn cai_ratio(&self, codon: &[u8]) -> f64 {
        let idx = codon_to_idx(codon);
        self.freqs[idx as usize] / self.max_freq[AA_OF_CODON[idx as usize] as usize]
    }

    /// Precomputed maximum frequency for an amino-acid index.
    #[inline]
    #[allow(dead_code)]
    pub fn max_freq_for_aa_idx(&self, aa_idx: u8) -> f64 {
        self.max_freq[aa_idx as usize]
    }
}

/// Encode a DNA base as 2 bits.
#[inline]
const fn base_to_bits(base: u8) -> u8 {
    match base {
        b'A' | b'a' => 0,
        b'C' | b'c' => 1,
        b'G' | b'g' => 2,
        b'T' | b't' | b'U' | b'u' => 3,
        _ => panic!("invalid DNA base"),
    }
}

/// Encode a 3-base DNA codon as a 6-bit index.
#[inline]
pub const fn codon_to_idx(codon: &[u8]) -> u8 {
    (base_to_bits(codon[0]) << 4) | (base_to_bits(codon[1]) << 2) | base_to_bits(codon[2])
}

/// Decode a 6-bit index back to a 3-base DNA codon.
#[inline]
#[allow(dead_code)]
pub const fn idx_to_codon(idx: u8) -> [u8; 3] {
    const BITS_TO_BASE: [u8; 4] = [b'A', b'C', b'G', b'T'];
    [
        BITS_TO_BASE[((idx >> 4) & 0b11) as usize],
        BITS_TO_BASE[((idx >> 2) & 0b11) as usize],
        BITS_TO_BASE[(idx & 0b11) as usize],
    ]
}

