/// One-character amino-acid codes, index = amino-acid index.
/// Index 20 is the stop codon '*'. There is no selenocysteine entry.
pub const AA_CHARS: [char; 21] = [
    'A', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'K', 'L', 'M', 'N', 'P', 'Q', 'R', 'S', 'T', 'V', 'W',
    'Y', '*',
];

/// Convert a one-character amino-acid string to its amino-acid index.
#[inline]
pub fn aa_to_idx(aa: &str) -> u8 {
    try_aa_to_idx(aa).unwrap_or_else(|| panic!("unknown amino acid: {}", aa))
}

/// Convert a one-character amino-acid string to its amino-acid index, if valid.
#[inline]
pub fn try_aa_to_idx(aa: &str) -> Option<u8> {
    match aa.as_bytes().first()? {
        b'A' => Some(0),
        b'C' => Some(1),
        b'D' => Some(2),
        b'E' => Some(3),
        b'F' => Some(4),
        b'G' => Some(5),
        b'H' => Some(6),
        b'I' => Some(7),
        b'K' => Some(8),
        b'L' => Some(9),
        b'M' => Some(10),
        b'N' => Some(11),
        b'P' => Some(12),
        b'Q' => Some(13),
        b'R' => Some(14),
        b'S' => Some(15),
        b'T' => Some(16),
        b'V' => Some(17),
        b'W' => Some(18),
        b'Y' => Some(19),
        b'*' => Some(20),
        _ => None,
    }
}

